{
  "@context": "https://schema.org",
  "@graph": [{
      "@type": "WebPage",
      "@id": "https://woodcontractingchicago.com/#webpage",
      "url": "https://woodcontractingchicago.com/",
      "name": "Chicago Home Remodeling & Renovation | Wood Contracting",
      "description": "Expert kitchen, bathroom & whole home remodeling in Chicago. Owner-operated team delivers superior craftsmanship. 500+ projects, 90% referral rate. Free quote.",
      "isPartOf": {
        "@id": "https://woodcontractingchicago.com/#website"
      },
      "about": {
        "@id": "https://woodcontractingchicago.com/#organization"
      },
      "mainEntity": {
        "@id": "https://woodcontractingchicago.com/#organization"
      },
      "inLanguage": "en-US"
    },
    {
      "@type": "FAQPage",
      "@id": "https://woodcontractingchicago.com/#faq",
      "name": "Frequently Asked Questions About Chicago Home Remodeling",
      "isPartOf": {
        "@id": "https://woodcontractingchicago.com/#webpage"
      },
      "mainEntity": [{
          "@type": "Question",
          "name": "How long does a typical bathroom or kitchen remodel take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Most bathroom renovations take 2-5 weeks from demolition to completion. Kitchen remodeling typically requires 4-6 weeks. Whole home renovations vary based on scope but generally range from 6-12 weeks. We provide detailed timelines during your free consultation and work diligently to meet deadlines."
          }
        },
        {
          "@type": "Question",
          "name": "How much does a home remodeling project cost in Chicago?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Project costs vary significantly based on scope, size, and material selections. Bathroom remodels typically range from $12,000-$55,000+. Kitchen renovations generally cost $15,000-$80,000+. Whole home remodeling projects vary widely based on square footage and complexity. Wood Contracting delivers superior value without showroom overhead or sales commissions. We provide transparent, detailed proposals during your free consultation."
          }
        },
        {
          "@type": "Question",
          "name": "Do you handle permits and HOA approvals?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Absolutely. We manage all permit applications, HOA submissions, and compliance requirements. With decades of experience navigating Chicago building codes and downtown condo associations, we handle the administrative work so you don't have to. We're familiar with requirements across all Chicago neighborhoods and building types."
          }
        },
        {
          "@type": "Question",
          "name": "What's included in your workmanship warranty?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Every Wood Contracting project comes with a 1-year workmanship warranty covering our installation and construction. We stand behind our work and ensure you're completely satisfied with the finished results. Material warranties are provided by manufacturers."
          }
        },
        {
          "@type": "Question",
          "name": "What makes Wood Contracting different from other Chicago contractors?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "We're owner-operated, which means Dillon Wood and our dedicated team complete your project, not subcontractors. With 500+ completed projects and a 90% referral rate, we've built our reputation on quality craftsmanship and transparent pricing. We don't have expensive showroom overhead, so your investment goes into your home, not our retail space."
          }
        },
        {
          "@type": "Question",
          "name": "What areas of Chicago do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "We primarily serve downtown Chicago neighborhoods including South Loop, West Loop, Lincoln Park, Logan Square, Wicker Park, Old Town, Bucktown, and surrounding areas. Our service area extends throughout Cook County from Hyde Park to Evanston. If your home is outside these areas, contact us to discuss your project."
          }
        },
        {
          "@type": "Question",
          "name": "Can I stay in my home during the remodeling?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, most clients remain in their homes during remodeling projects. We contain dust, protect your space, clean up daily, and work respectfully in your home. While some disruption is unavoidable, particularly during kitchen remodels, we minimize inconvenience wherever possible."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide design services?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "We partner with multiple experienced designers, including Emily Andersson Design. Alternatively, you can work with your own designer, or we can help you select materials and finishes without formal design services. We're flexible to match your needs and budget."
          }
        },
        {
          "@type": "Question",
          "name": "Are you licensed and insured?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, Wood Contracting is fully licensed and insured. We also meet or exceed all building and HOA requirements. We carry comprehensive liability insurance and workers' compensation coverage to protect you and our team throughout your project."
          }
        },
        {
          "@type": "Question",
          "name": "What if we encounter unexpected issues during construction?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Surprises occasionally happen, especially in older Chicago buildings. Hidden water damage, outdated wiring, or structural issues sometimes appear during demolition. We address problems immediately, explain your options clearly, and provide transparent pricing for necessary repairs. No hidden fees or surprise charges."
          }
        }
      ]
    }
  ]
}

